(function(){
'use strict';

function openPopup(el){
  el.classList.add('is-open');
  document.body.classList.add('eltiz-popup-open');
  el.removeAttribute('hidden');
  el.setAttribute('aria-modal','true');
  var firstFocusable = el.querySelector('a[href],button:not([disabled]),input,textarea,select,[tabindex]:not([tabindex="-1"])');
  if(firstFocusable) firstFocusable.focus();
}

function closePopup(el){
  el.classList.remove('is-open');
  document.body.classList.remove('eltiz-popup-open');
  el.setAttribute('hidden','');
  el.removeAttribute('aria-modal');
}

var popups = document.querySelectorAll('.eltiz-popup[data-popup-id]');

popups.forEach(function(popup){
  var trigger    = popup.dataset.popupTrigger    || 'load';
  var delay      = parseInt(popup.dataset.popupDelay    || 0, 10);
  var scroll     = parseInt(popup.dataset.popupScroll   || 50, 10);
  var cookieKey  = 'eltiz_popup_' + popup.dataset.popupId;
  var frequency  = popup.dataset.popupFrequency || 'always';

  // Check cookie/session.
  if(frequency === 'once' && sessionStorage.getItem(cookieKey)) return;
  if(frequency === 'session' && sessionStorage.getItem(cookieKey)) return;

  function show(){
    openPopup(popup);
    if(frequency !== 'always') sessionStorage.setItem(cookieKey, '1');
  }

  if(trigger === 'load'){
    if(delay > 0){ setTimeout(show, delay * 1000); }
    else { show(); }
  }

  if(trigger === 'exit-intent'){
    var fired = false;
    document.addEventListener('mouseleave', function(e){
      if(e.clientY <= 0 && !fired){ fired = true; show(); }
    });
  }

  if(trigger === 'scroll'){
    var scrollFired = false;
    window.addEventListener('scroll', function(){
      if(scrollFired) return;
      var pct = (window.scrollY / (document.body.scrollHeight - window.innerHeight)) * 100;
      if(pct >= scroll){ scrollFired = true; show(); }
    }, { passive: true });
  }

  if(trigger === 'time'){
    setTimeout(show, delay * 1000);
  }

  // Close on backdrop click.
  var backdrop = popup.querySelector('.eltiz-popup__backdrop');
  if(backdrop){ backdrop.addEventListener('click', function(){ closePopup(popup); }); }

  // Close buttons.
  popup.querySelectorAll('[data-popup-close]').forEach(function(btn){
    btn.addEventListener('click', function(){ closePopup(popup); });
  });

  // Escape key.
  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape' && popup.classList.contains('is-open')){ closePopup(popup); }
  });
});

// Manual open via data-popup-open="id".
document.querySelectorAll('[data-popup-open]').forEach(function(trigger){
  trigger.addEventListener('click', function(e){
    e.preventDefault();
    var id     = trigger.dataset.popupOpen;
    var target = document.querySelector('.eltiz-popup[data-popup-id="' + id + '"]');
    if(target) openPopup(target);
  });
});

})();
